import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.DaGSOal_.js";const u=JSON.parse('{"title":"Usage Guide","description":"","frontmatter":{"sidebar_position":4},"headers":[],"relativePath":"loading-screen-pro/usage.md","filePath":"loading-screen-pro/usage.md","lastUpdated":1777203998000}'),o={name:"loading-screen-pro/usage.md"};function s(i,e,l,d,g,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="usage-guide" tabindex="-1">Usage Guide <a class="header-anchor" href="#usage-guide" aria-label="Permalink to &quot;Usage Guide&quot;">​</a></h1><h2 id="quick-setup-2-minutes" tabindex="-1">Quick Setup (2 minutes) <a class="header-anchor" href="#quick-setup-2-minutes" aria-label="Permalink to &quot;Quick Setup (2 minutes)&quot;">​</a></h2><h3 id="step-1-—-open-plugin-settings" tabindex="-1">Step 1 — Open Plugin Settings <a class="header-anchor" href="#step-1-—-open-plugin-settings" aria-label="Permalink to &quot;Step 1 — Open Plugin Settings&quot;">​</a></h3><p>In Unreal Engine, go to <strong>Edit → Project Settings</strong>, then scroll down on the left side to <strong>Plugins → Loading Screen Pro</strong>.</p><h3 id="step-2-—-create-the-default-asset" tabindex="-1">Step 2 — Create the Default Asset <a class="header-anchor" href="#step-2-—-create-the-default-asset" aria-label="Permalink to &quot;Step 2 — Create the Default Asset&quot;">​</a></h3><p>Click the <strong>✚ Create &amp; Assign Default Loading Screen Asset</strong> button.</p><p>This automatically creates a <code>DA_LoadingScreen</code> Data Asset in your project&#39;s <code>Content/</code> folder and assigns it as the active loading screen.</p><h3 id="step-3-—-the-asset-opens-automatically" tabindex="-1">Step 3 — The Asset Opens Automatically <a class="header-anchor" href="#step-3-—-the-asset-opens-automatically" aria-label="Permalink to &quot;Step 3 — The Asset Opens Automatically&quot;">​</a></h3><p>The Data Asset opens in the Details panel. Here you configure everything:</p><ul><li><strong>Slideshow Images</strong> — add your background images (Texture2D)</li><li><strong>Background Color</strong> — fallback color if no images are added</li><li><strong>Hints</strong> — add loading tips that cycle during loading</li><li><strong>Music</strong> — assign a background sound</li><li><strong>Progress Bar</strong> — choose style (Bar / Segmented / Stepped)</li><li><strong>Spinner</strong> — choose style (Ring / Arc / Bars / Dots)</li></ul><h3 id="step-4-—-preview-the-loading-screen" tabindex="-1">Step 4 — Preview the Loading Screen <a class="header-anchor" href="#step-4-—-preview-the-loading-screen" aria-label="Permalink to &quot;Step 4 — Preview the Loading Screen&quot;">​</a></h3><p>At the top of the Data Asset, click the <strong>▶ Preview Loading Screen</strong> button.</p><p>A <strong>1280×720 preview window</strong> opens immediately — no Play-in-Editor required. You see all animations, transitions, and music playing live. Close the window when done.</p><h3 id="step-5-—-play-the-game" tabindex="-1">Step 5 — Play the Game <a class="header-anchor" href="#step-5-—-play-the-game" aria-label="Permalink to &quot;Step 5 — Play the Game&quot;">​</a></h3><p>Press <strong>Play</strong> or package the game. The loading screen appears automatically on every level transition — no Blueprint nodes required for basic use.</p><hr><h2 id="per-level-loading-screens" tabindex="-1">Per-Level Loading Screens <a class="header-anchor" href="#per-level-loading-screens" aria-label="Permalink to &quot;Per-Level Loading Screens&quot;">​</a></h2><p>To use a different loading screen on a specific map:</p><ol><li>Create a new Data Asset: <strong>right-click in Content Browser → Miscellaneous → Data Asset → LSPDataAsset</strong></li><li>Configure it as desired</li><li>Go to <strong>Project Settings → Plugins → Loading Screen Pro</strong></li><li>Under <strong>Per-Level Overrides</strong>, click <strong>+</strong> and set: <ul><li><strong>Map</strong> → select your level</li><li><strong>Loading Screen Asset</strong> → select the new Data Asset</li></ul></li></ol><hr><h2 id="blueprint-integration" tabindex="-1">Blueprint Integration <a class="header-anchor" href="#blueprint-integration" aria-label="Permalink to &quot;Blueprint Integration&quot;">​</a></h2><h3 id="show-hide-loading-screen-manually" tabindex="-1">Show / Hide Loading Screen manually <a class="header-anchor" href="#show-hide-loading-screen-manually" aria-label="Permalink to &quot;Show / Hide Loading Screen manually&quot;">​</a></h3><p>Use the <strong>Show Loading Screen</strong> and <strong>Hide Loading Screen</strong> Blueprint nodes to trigger loading screens manually — for example during a cutscene or custom transition.</p><h3 id="drive-progress-from-blueprint" tabindex="-1">Drive Progress from Blueprint <a class="header-anchor" href="#drive-progress-from-blueprint" aria-label="Permalink to &quot;Drive Progress from Blueprint&quot;">​</a></h3><p>Use the <strong>Set Loading Progress</strong> node and pass a float value between <code>0.0</code> and <code>1.0</code> to control the progress bar from code.</p><h3 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Event</th><th>When it fires</th></tr></thead><tbody><tr><td>On Slide Changed</td><td>Every time the active slide changes</td></tr><tr><td>On Loading Screen Shown</td><td>When the loading screen appears</td></tr><tr><td>On Loading Screen Hidden</td><td>When the loading screen disappears</td></tr></tbody></table><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Loading screen does not appear</strong> → Make sure a Data Asset is assigned in Project Settings. Loading screens only appear in <strong>packaged builds</strong> or <strong>Launch</strong> — not in Play-in-Editor (PIE).</p><p><strong>Progress bar stays at 0%</strong> → Set a <strong>Minimum Display Time</strong> (e.g. 2.0 seconds) in the Data Asset so the bar has time to animate.</p><p><strong>Music does not play</strong> → Music plays correctly in packaged builds. In the editor, use the <strong>▶ Preview Loading Screen</strong> button — not PIE.</p><p><strong>Images do not show</strong> → Make sure the textures are set to <strong>Texture2D</strong> and use a compatible format (RGBA8 or DXT5).</p>',33)])])}const p=t(o,[["render",s]]);export{u as __pageData,p as default};
